  `ends_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `mobile_image_url` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `desktop_storage_key` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile_storage_key` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtitle` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
