CREATE TABLE `delivery_batch_order_history` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch_order_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `previous_status` varchar(24) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `changed_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_delivery_batch_order_history_order_created` (`batch_order_id`,`created_at`),
  KEY `fk_delivery_batch_order_history_user` (`changed_by`),
  CONSTRAINT `fk_delivery_batch_order_history_order` FOREIGN KEY (`batch_order_id`) REFERENCES `delivery_batch_orders` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_batch_order_history_user` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
