--
-- Table structure for table `delivery_batch_orders`
--

DROP TABLE IF EXISTS `delivery_batch_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delivery_batch_orders` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `batch_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `order_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active_order_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `delivery_otp_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_attempts` int NOT NULL DEFAULT '0',
  `otp_expires_at` datetime(6) NOT NULL,
  `otp_consumed_at` datetime(6) DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `return_request_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active_return_request_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_delivery_batch_order` (`batch_id`,`order_id`),
  UNIQUE KEY `uk_delivery_active_order` (`active_order_id`),
  UNIQUE KEY `uk_delivery_active_return_request` (`active_return_request_id`),
  KEY `ix_delivery_batch_orders_batch_status` (`batch_id`,`status`),
  KEY `ix_delivery_batch_orders_order` (`order_id`),
  KEY `ix_delivery_batch_orders_return_request` (`return_request_id`),
  CONSTRAINT `fk_delivery_batch_orders_active_order` FOREIGN KEY (`active_order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_batch_orders_active_return_request` FOREIGN KEY (`active_return_request_id`) REFERENCES `return_requests` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_batch_orders_batch` FOREIGN KEY (`batch_id`) REFERENCES `delivery_batches` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_batch_orders_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_batch_orders_return_request` FOREIGN KEY (`return_request_id`) REFERENCES `return_requests` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_delivery_batch_orders_one_target` CHECK ((((`order_id` is null) and (`return_request_id` is not null)) or ((`order_id` is not null) and (`return_request_id` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

